// Inhalte für istdaskosher.de
// Antworten nach traditioneller (orthodoxer) Halacha; wo Strömungen oder Bräuche abweichen, steht es in der Erklärung.
// a: "ja" = erlaubt/koscher, "nein" = verboten/nicht koscher, "kommt" = kommt drauf an

window.QUESTIONS = [
  // Essen
  { cat: "Essen", q: "Gummibärchen mit Schweinegelatine essen", a: "nein", e: "Gelatine aus Schweinen ist nicht koscher. Es gibt aber koschere Fruchtgummis – mit Gelatine von koscher geschlachteten Rindern, Fischgelatine oder pflanzlichen Geliermitteln.", src: "3. Mose 11,7", lv: 1 },
  { cat: "Essen", q: "Shrimps essen", a: "nein", e: "Aus dem Wasser sind nur Tiere mit Flossen und Schuppen erlaubt. Garnelen, Muscheln, Hummer und Tintenfisch fallen alle raus.", src: "3. Mose 11,9–12", lv: 1 },
  { cat: "Essen", q: "Lachs essen", a: "ja", e: "Lachs hat Flossen und Schuppen – damit ist er koscher. Fisch gilt außerdem als „parve“, also weder fleischig noch milchig.", src: "3. Mose 11,9", lv: 1 },
  { cat: "Essen", q: "Einen Cheeseburger essen", a: "nein", e: "Fleisch und Milch werden nie zusammen gegessen oder gekocht. Die Regel geht auf den Vers zurück, man solle das Böcklein nicht in der Milch seiner Mutter kochen – er steht dreimal in der Tora.", src: "2. Mose 23,19", lv: 1 },
  { cat: "Essen", q: "Hähnchen in Sahnesoße essen", a: "nein", e: "Von der Tora her betrifft das Verbot nur Säugetiere, die Rabbiner haben es aber auf Geflügel ausgeweitet. Hähnchen zählt deshalb als „fleischig“.", src: "Talmud, Chullin 104b", lv: 2 },
  { cat: "Essen", q: "Überbackenen Fisch mit Käse essen", a: "kommt", e: "Fisch ist parve und darf in den meisten Gemeinden mit Milch gegessen werden. Viele sephardische Juden verzichten aber darauf – gestützt auf einen Hinweis von Rabbi Josef Karo, dem Verfasser des Schulchan Aruch.", src: "Beit Josef, Jore De’a 87", lv: 3 },
  { cat: "Essen", q: "Kamelfleisch essen", a: "nein", e: "Erlaubt sind Säugetiere, die wiederkäuen und gespaltene Hufe haben. Das Kamel käut wieder, hat aber keine gespaltenen Hufe – die Tora nennt es ausdrücklich.", src: "3. Mose 11,4", lv: 2 },
  { cat: "Essen", q: "Giraffenfleisch essen", a: "ja", e: "Die Giraffe ist ein Wiederkäuer mit gespaltenen Hufen und damit eigentlich koscher. Gegessen wird sie trotzdem praktisch nie: Sie ist selten, geschützt und eine Schächtung wäre enormer Aufwand.", src: "3. Mose 11,3", lv: 3 },
  { cat: "Essen", q: "Kaninchenfleisch essen", a: "nein", e: "Hasen und Kaninchen haben keine gespaltenen Hufe. Der Hase wird in der Tora sogar namentlich als unrein genannt.", src: "3. Mose 11,6", lv: 2 },
  { cat: "Essen", q: "Heuschrecken essen", a: "kommt", e: "Die Tora erlaubt tatsächlich vier Arten von Heuschrecken. Heute weiß aber fast niemand mehr sicher, welche das sind – nur jemenitische und einige nordafrikanische Juden haben eine Überlieferung und essen sie.", src: "3. Mose 11,22", lv: 3 },
  { cat: "Essen", q: "Honig essen", a: "ja", e: "Bienen sind nicht koscher, ihr Honig aber schon. Der Talmud erklärt: Honig ist Nektar, den die Biene nur sammelt und verarbeitet – er stammt nicht aus ihrem Körper wie Milch.", src: "Talmud, Bechorot 7b", lv: 2 },
  { cat: "Essen", q: "Truthahn essen", a: "ja", e: "Bei Vögeln braucht es eine Überlieferung, welche Arten erlaubt sind. Der Truthahn kam erst aus Amerika und hatte keine – er wurde trotzdem fast überall als koscher akzeptiert.", src: "3. Mose 11,13–19", lv: 2 },
  { cat: "Essen", q: "Straußenfleisch essen", a: "nein", e: "Der Strauß steht nach traditioneller Übersetzung in der Liste der verbotenen Vögel.", src: "3. Mose 11,16", lv: 3 },
  { cat: "Essen", q: "Ein Ei mit Blutfleck essen", a: "nein", e: "Blut zu essen ist verboten. Eier werden deshalb vor dem Kochen aufgeschlagen und kontrolliert, eines mit Blutfleck wird weggeworfen. Bei heutigen unbefruchteten Eiern sind manche Rabbiner großzügiger.", src: "Schulchan Aruch, Jore De’a 66", lv: 2 },
  { cat: "Feiertage", q: "Brot an Pessach essen", a: "nein", e: "Eine Woche lang ist alles Gesäuerte (Chametz) aus Weizen, Gerste, Roggen, Hafer und Dinkel tabu. Stattdessen gibt es Mazza – Brot, das in unter 18 Minuten fertig gebacken sein muss.", src: "2. Mose 12,15", lv: 1 },
  { cat: "Feiertage", q: "Reis an Pessach essen", a: "kommt", e: "Aschkenasische Juden verzichten an Pessach traditionell auf Hülsenfrüchte, Reis und Mais (Kitniot), sephardische nicht. Die konservative Bewegung hat Kitniot 2015 auch für Aschkenasen erlaubt.", src: "Rema zu Orach Chajim 453", lv: 3 },
  { cat: "Essen", q: "Schwertfisch essen", a: "nein", e: "Junge Schwertfische haben Schuppen, erwachsene verlieren sie. Orthodoxe Autoritäten sehen ihn deshalb als nicht koscher, die konservative Bewegung hat ihn zeitweise erlaubt.", src: "3. Mose 11,10", lv: 3 },
  { cat: "Essen", q: "Kaviar vom Stör essen", a: "nein", e: "Der Stör hat harte Knochenschuppen, die sich nicht ohne Verletzung der Haut ablösen lassen – nach orthodoxer Sicht zählen sie nicht. Konservative Rabbiner sehen das anders.", src: "Ramban zu 3. Mose 11,9", lv: 3 },
  { cat: "Essen", q: "Wein aus einem normalen Supermarkt trinken", a: "nein", e: "Bei Wein gelten strengere Regeln als bei anderen Getränken: Er muss unter jüdischer Aufsicht hergestellt sein. Erkennbar ist koscherer Wein am Siegel auf dem Etikett.", src: "Schulchan Aruch, Jore De’a 123", lv: 3 },
  { cat: "Essen", q: "Direkt nach dem Schnitzel ein Milcheis essen", a: "nein", e: "Nach Fleisch wartet man, bevor man Milchiges isst – meist sechs Stunden. Deutsche Juden warten traditionell drei, niederländische nur eine Stunde.", src: "Schulchan Aruch, Jore De’a 89", lv: 2 },
  { cat: "Essen", q: "Erst ein Milcheis, gleich danach ein Schnitzel essen", a: "ja", e: "Andersherum geht es schneller: Mund ausspülen, etwas Neutrales essen, Hände waschen – fertig. Nur nach Hartkäse warten viele genauso lange wie nach Fleisch.", src: "Schulchan Aruch, Jore De’a 89,2", lv: 3 },
  { cat: "Essen", q: "Schweinefleisch essen, um nicht zu verhungern", a: "ja", e: "Ein Menschenleben zu retten (Pikuach Nefesch) geht fast allen Geboten vor. Wer sonst verhungern würde, muss sogar essen, was er findet.", src: "Talmud, Joma 85b", lv: 2 },

  // Schabbat & Feiertage
  { cat: "Schabbat", q: "Am Schabbat das Licht anschalten", a: "nein", e: "Am Schabbat ruhen 39 Arten von Arbeit, darunter Feuer entzünden. Strom einschalten zählt nach orthodoxer Auffassung dazu.", src: "2. Mose 35,3", lv: 1 },
  { cat: "Schabbat", q: "Am Schabbat Licht über eine Zeitschaltuhr, die man vorher eingestellt hat", a: "ja", e: "Die „Schabbatuhr“ ist ein Klassiker: Alles, was vor Schabbat eingestellt wurde, darf von selbst laufen.", src: "Schmirat Schabbat ke-Hilchata 13", lv: 2 },
  { cat: "Schabbat", q: "Am Schabbat mit dem Auto zur Synagoge fahren", a: "nein", e: "Nach orthodoxer Halacha ist Autofahren am Schabbat verboten, unter anderem wegen der Zündung. Die konservative Bewegung hat die Fahrt zur Synagoge 1950 erlaubt.", src: "Responsum zum Schabbat, Rabbinical Assembly 1950", lv: 1 },
  { cat: "Schabbat", q: "Am Schabbat jemanden mit dem Auto ins Krankenhaus fahren", a: "ja", e: "Nicht nur erlaubt, sondern Pflicht: Wo Lebensgefahr besteht, tritt der Schabbat zurück. Der Talmud sagt, man soll einen Schabbat brechen, damit der Mensch noch viele Schabbatot halten kann.", src: "Talmud, Joma 85b", lv: 2 },
  { cat: "Schabbat", q: "Am Schabbat am Handy chatten", a: "nein", e: "Bildschirm, Strom, Schreiben – gleich mehrere Verbote auf einmal. Viele genießen gerade das: 25 Stunden offline.", lv: 1 },
  { cat: "Schabbat", q: "Am Schabbat mit dem Schabbat-Aufzug fahren", a: "ja", e: "Der Schabbat-Aufzug hält automatisch auf jeder Etage, niemand drückt einen Knopf. Die meisten orthodoxen Rabbiner erlauben ihn, einige sehr strenge nicht.", lv: 2 },
  { cat: "Schabbat", q: "Am Schabbat Geld anfassen", a: "nein", e: "Geld ist „Mukze“ – Dinge, die man am Schabbat nicht braucht, bewegt man gar nicht erst.", src: "Schulchan Aruch, Orach Chajim 308–310", lv: 2 },
  { cat: "Schabbat", q: "Am Schabbat Essen auf einer Warmhalteplatte, die vorher angeschaltet wurde", a: "ja", e: "Die „Plata“ oder „Blech“ läuft seit Freitag. Darauf bleibt fertiges Essen warm – der Grund, warum es samstags oft Tscholent gibt, einen Eintopf, der über Nacht schmort.", src: "Schulchan Aruch, Orach Chajim 253", lv: 2 },
  { cat: "Schabbat", q: "Am Schabbat in der Stadt einen Schlüssel in der Hosentasche tragen", a: "kommt", e: "Tragen im öffentlichen Raum ist verboten – außer es gibt einen „Eruv“, eine symbolische Umzäunung, oft aus Drähten zwischen Masten. Manhattan, London und viele andere Städte haben einen.", src: "Talmud, Traktat Eruvin", lv: 3 },
  { cat: "Feiertage", q: "An Jom Kippur essen, wenn man schwer krank ist", a: "ja", e: "An Jom Kippur wird 25 Stunden gefastet – aber nicht, wenn es die Gesundheit gefährdet. Dann ist Essen sogar Pflicht.", src: "Schulchan Aruch, Orach Chajim 618", lv: 2 },

  // Körper & Kleidung
  { cat: "Körper", q: "Ein Tattoo stechen lassen", a: "nein", e: "Tätowierungen verbietet die Tora ausdrücklich. Ein verbreiteter Mythos stimmt aber nicht: Mit Tattoo darf man trotzdem auf einem jüdischen Friedhof beerdigt werden.", src: "3. Mose 19,28", lv: 1 },
  { cat: "Körper", q: "Den Bart mit einer Rasierklinge rasieren", a: "nein", e: "Verboten ist, die Ecken des Bartes mit einer Klinge zu „zerstören“. Ein Elektrorasierer, der wie eine Schere schneidet, ist nach den meisten Meinungen erlaubt.", src: "3. Mose 19,27", lv: 2 },
  { cat: "Körper", q: "Einen Pulli aus Wolle und Leinen gemischt tragen", a: "nein", e: "Diese Mischung heißt Schaatnes und ist verboten. Es gibt sogar Labore, die Kleidung darauf untersuchen.", src: "5. Mose 22,11", lv: 3 },
  { cat: "Körper", q: "Ohrlöcher stechen", a: "ja", e: "Dafür gibt es kein Verbot – Ohrringe werden schon in der Tora erwähnt.", src: "2. Mose 32,2", lv: 3 },
  { cat: "Körper", q: "In den Wochen zwischen Pessach und Schawuot zum Friseur gehen", a: "kommt", e: "In der Omer-Zeit gelten Trauerbräuche, viele lassen sich die Haare nicht schneiden. Wann genau, ist je nach Gemeinde verschieden – am 33. Tag (Lag baOmer) gehen viele zum Friseur.", src: "Schulchan Aruch, Orach Chajim 493", lv: 3 },
  { cat: "Körper", q: "Einer Frau oder einem Mann zur Begrüßung die Hand geben", a: "kommt", e: "Viele orthodoxe Juden berühren das andere Geschlecht außerhalb der Familie nicht („Schomer Negia“). Andere geben die Hand, um niemanden zu beschämen. Liberale Juden sehen darin kein Problem.", src: "Schulchan Aruch, Even haEser 21", lv: 3 },

  // Alltag
  { cat: "Alltag", q: "Ein Blatt mit dem hebräischen Gottesnamen in den Müll werfen", a: "nein", e: "Geschriebene Gottesnamen werden nicht vernichtet, sondern in einer Genisa gesammelt und begraben. Deshalb schreiben manche auch auf Deutsch „G’tt“.", src: "5. Mose 12,3–4", lv: 3 },
  { cat: "Alltag", q: "Einen nichtjüdischen Freund zum Schabbatessen einladen", a: "ja", e: "Gäste einzuladen gilt als große Mitzwa – Abraham ist dafür das Vorbild. Das Essen ist sowieso vor Schabbat gekocht.", src: "1. Mose 18", lv: 1 },
  { cat: "Alltag", q: "Eine kleine Notlüge, um Streit zu vermeiden", a: "ja", e: "Der Talmud erlaubt, um des Friedens willen die Wahrheit zu „verändern“ – und führt als Beispiel sogar Gott an, der Saras Worte gegenüber Abraham abmilderte.", src: "Talmud, Jevamot 65b", lv: 2 },
  { cat: "Alltag", q: "Von einem jüdischen Freund Zinsen für einen Kredit verlangen", a: "nein", e: "Zinsen unter Juden sind verboten. Damit Banken trotzdem funktionieren, gibt es einen Vertrag namens „Heter Iska“, der den Kredit zur Geschäftspartnerschaft macht.", src: "2. Mose 22,24", lv: 3 },
  { cat: "Alltag", q: "Einen Hund als Haustier halten", a: "ja", e: "Haustiere sind erlaubt. Es gibt sogar eine Regel, die Tiere zuerst zu füttern, bevor man selbst isst.", src: "Talmud, Berachot 40a", lv: 1 },
  { cat: "Alltag", q: "Ein Tier unnötig quälen", a: "nein", e: "„Tza’ar ba’alei chajim“ – Tierleid zu verursachen ist verboten. Selbst am Schabbat darf man einem Tier in Not helfen.", src: "Talmud, Bava Metzia 32b", lv: 1 },
  { cat: "Alltag", q: "Am Schabbat live Fußball im Fernsehen schauen", a: "nein", e: "Den Fernseher anzuschalten ist am Schabbat verboten. Und selbst wenn er läuft: Sich davon unterhalten zu lassen, passt für die meisten Rabbiner nicht zum Ruhetag.", lv: 1 },

  // ---- Mehr Essen ----
  { cat: "Essen", q: "Blutwurst essen", a: "nein", e: "Blut zu essen ist eines der strengsten Speiseverbote. Koscheres Fleisch wird deshalb gewässert und gesalzen, damit das Blut herausgezogen wird.", src: "3. Mose 17,10–14", lv: 1 },
  { cat: "Essen", q: "Ein rosa gebratenes Steak vom koscheren Rind essen", a: "ja", e: "Nach dem Salzen gilt das Blut als entfernt. Der rosa Fleischsaft, der danach noch austritt, zählt nicht als verbotenes Blut.", src: "Schulchan Aruch, Jore De’a 67–69", lv: 3 },
  { cat: "Essen", q: "Rinderfilet essen", a: "kommt", e: "Das Filet stammt aus dem Hinterviertel. Dort müssen Ischiasnerv und bestimmte Fette mühsam entfernt werden. In Israel wird das gemacht, außerhalb Israels verkaufen koschere Metzger das Hinterviertel meist gar nicht.", src: "1. Mose 32,33", lv: 3 },
  { cat: "Essen", q: "Ente essen", a: "ja", e: "Ente und Gans gelten nach alter Überlieferung als koschere Vögel – geschächtet natürlich.", src: "Schulchan Aruch, Jore De’a 82", lv: 2 },
  { cat: "Essen", q: "Taube essen", a: "ja", e: "Tauben sind koscher – sie wurden im Tempel sogar als Opfer dargebracht.", src: "3. Mose 1,14", lv: 3 },
  { cat: "Essen", q: "Ein Straußenei essen", a: "nein", e: "Eier folgen dem Tier, von dem sie stammen. Der Strauß ist nicht koscher – also auch sein Ei nicht.", src: "Talmud, Bechorot 5b", lv: 3 },
  { cat: "Essen", q: "Kamelmilch trinken", a: "nein", e: "Milch folgt ebenfalls dem Tier. Nur Milch von koscheren Tieren wie Kuh, Ziege oder Schaf ist erlaubt.", src: "Talmud, Bechorot 6b", lv: 3 },
  { cat: "Essen", q: "Ziegenmilch trinken", a: "ja", e: "Die Ziege ist ein Wiederkäuer mit gespaltenen Hufen – ihre Milch ist koscher.", src: "5. Mose 14,4", lv: 2 },
  { cat: "Essen", q: "Pferdefleisch essen", a: "nein", e: "Das Pferd käut nicht wieder und hat keine gespaltenen Hufe.", src: "3. Mose 11,3", lv: 1 },
  { cat: "Essen", q: "Hirsch essen, der bei der Jagd geschossen wurde", a: "nein", e: "Hirsch und Reh sind koschere Tiere – aber nur, wenn sie geschächtet werden. Ein geschossenes Tier ist nicht koscher.", src: "5. Mose 14,5; Schulchan Aruch, Jore De’a 1", lv: 3 },
  { cat: "Essen", q: "Thunfisch essen", a: "ja", e: "Thunfisch hat Flossen und Schuppen. Konserven brauchen trotzdem ein Siegel, weil in der Fabrik oft auch andere Fische verarbeitet werden.", src: "3. Mose 11,9", lv: 2 },
  { cat: "Essen", q: "Aal essen", a: "nein", e: "Der Aal hat zwar winzige Schuppen in der Haut, aber keine, die man ablösen kann – er gilt als nicht koscher.", src: "Talmud, Chullin 66b", lv: 2 },
  { cat: "Essen", q: "Wels essen", a: "nein", e: "Welse haben keine Schuppen.", src: "3. Mose 11,10", lv: 3 },
  { cat: "Essen", q: "Haifisch essen", a: "nein", e: "Haie haben keine echten Schuppen, sondern eine raue Haut aus Hautzähnchen – nicht koscher.", src: "3. Mose 11,10", lv: 2 },
  { cat: "Essen", q: "Karpfen essen", a: "ja", e: "Karpfen ist koscher und der Klassiker für „Gefilte Fisch“ am Schabbat.", src: "3. Mose 11,9", lv: 2 },
  { cat: "Essen", q: "Hering essen", a: "ja", e: "Hering hat Flossen und Schuppen – eingelegter Hering ist in der aschkenasischen Küche beliebt.", src: "3. Mose 11,9", lv: 2 },
  { cat: "Essen", q: "Calamari essen", a: "nein", e: "Tintenfische haben weder Flossen noch Schuppen.", src: "3. Mose 11,10", lv: 1 },
  { cat: "Essen", q: "Froschschenkel essen", a: "nein", e: "Frösche gehören zu den „Kriechtieren“, die nicht gegessen werden.", lv: 1 },
  { cat: "Essen", q: "Weinbergschnecken essen", a: "nein", e: "Schnecken sind nicht koscher.", src: "3. Mose 11,42", lv: 1 },
  { cat: "Essen", q: "Salat mit einer Blattlaus darauf essen", a: "nein", e: "Auch kleine Insekten sind verboten. Salat und Kräuter werden deshalb gründlich gewaschen und gegen das Licht geprüft.", src: "3. Mose 11,41", lv: 3 },
  { cat: "Essen", q: "Erdbeeren essen", a: "ja", e: "Obst und Gemüse sind grundsätzlich koscher und „parve“ – man muss sie nur auf Insekten prüfen.", src: "1. Mose 1,29", lv: 1 },
  { cat: "Essen", q: "Butter auf dem Brot zum Hähnchenschnitzel essen", a: "nein", e: "Butter ist milchig, Hähnchen gilt als fleischig – zusammen geht das nicht.", src: "Schulchan Aruch, Jore De’a 87", lv: 2 },
  { cat: "Essen", q: "Pflanzenmargarine zum Fleisch essen", a: "ja", e: "Rein pflanzliche Margarine ist parve und darf zu Fleisch gegessen werden.", lv: 2 },
  { cat: "Essen", q: "Einen Rindfleisch-Burger mit veganem Käse essen", a: "kommt", e: "Erlaubt ist es, weil kein echter Käse drin ist. Manche achten aber auf „Mar’it Ajin“ – den Anschein, man esse Fleisch mit Milch – und legen die Packung gut sichtbar daneben.", src: "Rema zu Jore De’a 87,3", lv: 3 },
  { cat: "Essen", q: "Salamipizza essen", a: "nein", e: "Fleischwurst und Käse auf einer Pizza – klassisch verboten.", src: "2. Mose 23,19", lv: 1 },
  { cat: "Essen", q: "Gouda aus dem normalen Supermarkt essen", a: "nein", e: "Käse braucht nach traditioneller Halacha jüdische Aufsicht bei der Herstellung („Gewinat Akum“), unter anderem wegen des Labs aus Kälbermägen.", src: "Talmud, Avoda Sara 35a", lv: 3 },
  { cat: "Essen", q: "Brot vom normalen Bäcker essen", a: "kommt", e: "Viele Aschkenasen kaufen Brot vom nichtjüdischen Bäcker, wenn die Zutaten koscher sind („Pat Palter“). Strengere essen nur Brot, bei dem ein Jude mitgebacken hat.", src: "Schulchan Aruch, Jore De’a 112", lv: 3 },
  { cat: "Essen", q: "Whisky aus Sherryfässern trinken", a: "kommt", e: "Sherry ist Wein, und für Wein gelten strenge Regeln. Ob die Reste im Fass den Whisky betreffen, ist umstritten – manche Rabbiner erlauben ihn, andere nicht.", lv: 3 },
  { cat: "Essen", q: "Fruchtgummi mit Pektin statt Gelatine essen", a: "ja", e: "Pektin stammt aus Früchten und ist pflanzlich – mit Siegel steht dem nichts im Weg.", lv: 2 },
  { cat: "Essen", q: "Leitungswasser trinken", a: "ja", e: "Wasser ist koscher. 2004 gab es in New York trotzdem Streit, weil winzige Ruderfußkrebse im Leitungswasser gefunden wurden – viele kauften daraufhin Filter.", lv: 1 },

  // ---- Feiertage ----
  { cat: "Feiertage", q: "Kartoffeln an Pessach essen", a: "ja", e: "Kartoffeln sind weder Getreide noch Hülsenfrucht – an Pessach ein Grundnahrungsmittel.", lv: 1 },
  { cat: "Feiertage", q: "Quinoa an Pessach essen", a: "kommt", e: "Quinoa war früher unbekannt. Viele Rabbiner sehen es nicht als Kitniot und erlauben es, andere sind vorsichtig.", lv: 3 },
  { cat: "Feiertage", q: "Bier an Pessach trinken", a: "nein", e: "Bier wird aus vergorener Gerste gebraut – reinstes Chametz.", src: "2. Mose 12,15", lv: 2 },
  { cat: "Feiertage", q: "Mazza am Sederabend essen", a: "ja", e: "Am ersten Pessachabend ist es sogar Pflicht, Mazza zu essen.", src: "2. Mose 12,18", lv: 1 },
  { cat: "Feiertage", q: "Lederschuhe an Jom Kippur tragen", a: "nein", e: "An Jom Kippur verzichtet man auf Essen, Trinken, Waschen, Eincremen, Lederschuhe und Intimität. Viele tragen deshalb Turnschuhe aus Stoff in der Synagoge.", src: "Talmud, Joma 73b", lv: 3 },
  { cat: "Feiertage", q: "An Jom Kippur ein Glas Wasser trinken (gesund)", a: "nein", e: "Gefastet wird ohne Essen und ohne Trinken – 25 Stunden lang.", src: "3. Mose 16,29", lv: 2 },
  { cat: "Feiertage", q: "Chanukka-Kerzen am Schabbat anzünden", a: "nein", e: "Am Freitag werden die Chanukka-Lichter vor Schabbatbeginn angezündet – am Schabbat selbst darf man kein Feuer entzünden.", src: "Schulchan Aruch, Orach Chajim 679", lv: 2 },
  { cat: "Feiertage", q: "Sich an Purim betrinken", a: "kommt", e: "Der Talmud sagt, man solle an Purim trinken, bis man „Verflucht sei Haman“ und „Gesegnet sei Mordechai“ nicht mehr unterscheiden kann. Viele Rabbiner sagen: Ein wenig mehr als sonst und dann schlafen reicht.", src: "Talmud, Megilla 7b", lv: 3 },
  { cat: "Feiertage", q: "Sich an Purim verkleiden", a: "ja", e: "Das ist ein fester Brauch – ähnlich wie Karneval, mit Kostümen und Umzügen.", src: "Rema zu Orach Chajim 696,8", lv: 1 },
  { cat: "Feiertage", q: "An Sukkot in der Laubhütte essen", a: "ja", e: "Eine Woche lang isst man in der Sukka, einer Hütte mit Dach aus Zweigen – das ist ein Gebot.", src: "3. Mose 23,42", lv: 1 },
  { cat: "Feiertage", q: "Am 9. Av (Tischa beAw) essen", a: "nein", e: "Am 9. Av wird um die Zerstörung des Tempels getrauert und wie an Jom Kippur gefastet.", src: "Schulchan Aruch, Orach Chajim 554", lv: 2 },

  // ---- Mehr Schabbat ----
  { cat: "Schabbat", q: "Am Schabbat Fahrrad fahren", a: "nein", e: "Die meisten orthodoxen Rabbiner verbieten es – unter anderem, weil man es bei einer Panne reparieren könnte und weil es als Werktagstätigkeit gilt.", lv: 2 },
  { cat: "Schabbat", q: "Am Schabbat spazieren gehen", a: "ja", e: "Ein Spaziergang ist ideal für den Ruhetag – solange man nichts trägt oder es einen Eruv gibt.", lv: 1 },
  { cat: "Schabbat", q: "Am Schabbat schwimmen gehen", a: "nein", e: "Die Rabbiner haben Schwimmen am Schabbat verboten, unter anderem damit man keine Schwimmhilfen baut oder Wasser auswringt.", src: "Schulchan Aruch, Orach Chajim 339,2", lv: 3 },
  { cat: "Schabbat", q: "Am Schabbat warm duschen", a: "nein", e: "Durch die Entnahme von warmem Wasser strömt kaltes Wasser in den Boiler und wird erhitzt – das gilt als Kochen.", src: "Schulchan Aruch, Orach Chajim 326", lv: 3 },
  { cat: "Schabbat", q: "Am Schabbat Blumen pflücken", a: "nein", e: "Pflücken zählt als Ernten – eine der 39 verbotenen Arbeiten.", src: "Mischna, Schabbat 7,2", lv: 3 },
  { cat: "Schabbat", q: "Am Schabbat ein Buch lesen", a: "ja", e: "Lesen ist erlaubt und beliebt – nur Geschäftliches und Werktagsdinge meidet man.", lv: 1 },
  { cat: "Schabbat", q: "Am Schabbat Schach spielen", a: "ja", e: "Brettspiele sind erlaubt, solange man nichts schreibt – also ohne Punkte zu notieren.", lv: 2 },
  { cat: "Schabbat", q: "Am Schabbat Kartoffeln kochen", a: "nein", e: "Kochen ist eine der 39 Arbeiten. Gekocht wird vor Schabbat.", src: "Mischna, Schabbat 7,2", lv: 2 },
  { cat: "Schabbat", q: "Am Schabbat Fotos machen", a: "nein", e: "Fotografieren gilt als verboten – mit dem Handy sowieso wegen des Stroms.", lv: 2 },
  { cat: "Schabbat", q: "Am Schabbat Klavier spielen", a: "nein", e: "Die Rabbiner haben Musikinstrumente verboten, damit niemand ein kaputtes Instrument repariert.", src: "Schulchan Aruch, Orach Chajim 338,1", lv: 2 },
  { cat: "Schabbat", q: "Am Schabbat einkaufen gehen", a: "nein", e: "Kaufen und Verkaufen ist am Schabbat verboten.", src: "Nehemia 10,32", lv: 1 },
  { cat: "Schabbat", q: "Am Schabbat den Notarzt anrufen", a: "ja", e: "Bei Lebensgefahr ruft man sofort an – zögern wäre sogar falsch.", src: "Talmud, Joma 84b", lv: 1 },
  { cat: "Schabbat", q: "Am Schabbat einen Regenschirm aufspannen", a: "nein", e: "Einen Schirm aufzuspannen gilt als „Zelt bauen“ und ist rabbinisch verboten.", src: "Mischna Berura 315", lv: 3 },
  { cat: "Schabbat", q: "Am Schabbat mit Zahnpasta Zähne putzen", a: "kommt", e: "Manche Rabbiner verbieten Zahnpasta, weil man sie verstreicht. Andere erlauben sie, vor allem flüssige.", lv: 3 },
  { cat: "Schabbat", q: "Am Schabbat joggen gehen", a: "nein", e: "Sport, der anstrengt, passt nach den meisten Rabbinern nicht zum Ruhetag.", src: "Schulchan Aruch, Orach Chajim 301,2", lv: 2 },
  { cat: "Schabbat", q: "Am Freitagabend Kerzen anzünden", a: "ja", e: "Das Anzünden der Schabbatkerzen kurz vor Sonnenuntergang ist ein Gebot – meist von der Frau des Hauses.", src: "Schulchan Aruch, Orach Chajim 263", lv: 1 },
  { cat: "Schabbat", q: "Am Schabbat Make-up auftragen", a: "nein", e: "Schminken zählt als „Färben“ und ist verboten.", src: "Schulchan Aruch, Orach Chajim 303,25", lv: 3 },

  // ---- Mehr Körper ----
  { cat: "Körper", q: "Nach dem Tod Organe spenden", a: "kommt", e: "Ein Leben zu retten ist ein großes Gebot. Umstritten ist, ob der Hirntod als Tod gilt: Israels Oberrabbinat hat ihn 1986 anerkannt, viele ultraorthodoxe Rabbiner nicht.", lv: 3 },
  { cat: "Körper", q: "Eine Schönheits-OP machen lassen", a: "kommt", e: "Den eigenen Körper unnötig zu verletzen ist verboten. Manche Rabbiner erlauben eine OP, wenn sie seelisches Leid lindert, andere sind streng.", src: "Responsa Igrot Mosche, Choschen Mischpat 2,66", lv: 3 },
  { cat: "Körper", q: "Zigaretten rauchen", a: "kommt", e: "Früher war Rauchen kein Thema. Heute verbieten viele Rabbiner es wegen der Gesundheitsgefahr, andere halten es nur für sehr schlecht.", lv: 3 },
  { cat: "Körper", q: "Sich nach dem Tod verbrennen lassen (Feuerbestattung)", a: "nein", e: "Nach orthodoxer Halacha wird der Körper in der Erde begraben. Die Reformbewegung lehnt die Einäscherung nicht grundsätzlich ab.", src: "5. Mose 21,23", lv: 3 },
  { cat: "Körper", q: "Als Mann ohne Kopfbedeckung beten", a: "nein", e: "Orthodoxe Männer tragen beim Beten eine Kippa oder einen Hut – aus Ehrfurcht vor Gott.", src: "Schulchan Aruch, Orach Chajim 91,3", lv: 2 },
  { cat: "Körper", q: "Als Frau Hosen tragen", a: "kommt", e: "Viele orthodoxe Frauen tragen nur Röcke, weil Männer- und Frauenkleidung getrennt sein sollen. Andere Rabbiner sehen Damenhosen als Frauenkleidung an.", src: "5. Mose 22,5", lv: 3 },

  // ---- Mehr Alltag ----
  { cat: "Alltag", q: "Über jemanden lästern – auch wenn es stimmt", a: "nein", e: "„Laschon Hara“, schlecht über andere reden, ist verboten, selbst wenn es wahr ist.", src: "3. Mose 19,16", lv: 2 },
  { cat: "Alltag", q: "Mehr als 20 Prozent seines Einkommens spenden", a: "nein", e: "Überraschend: Der Talmud begrenzt Spenden auf ein Fünftel – damit man nicht selbst arm und abhängig wird.", src: "Talmud, Ketubot 50a", lv: 3 },
  { cat: "Alltag", q: "Zum Spaß auf die Jagd gehen", a: "nein", e: "Rabbi Jecheskel Landau schrieb im 18. Jahrhundert, die Jagd zum Vergnügen sei für Juden verboten – Tiere ohne Not zu töten passe nicht zur Tora.", src: "Noda biJehuda, Jore De’a 2,10", lv: 3 },
  { cat: "Alltag", q: "Den eigenen Hund kastrieren lassen", a: "nein", e: "Das Verbot der Kastration gilt auch für Tiere. Manche lassen es von einem nichtjüdischen Tierarzt machen – auch das ist umstritten.", src: "3. Mose 22,24", lv: 3 },
  { cat: "Alltag", q: "Eine Mesusa an die Haustür hängen", a: "ja", e: "Die Mesusa, eine kleine Kapsel mit einem Pergament, gehört an jeden Türpfosten eines jüdischen Hauses – das ist ein Gebot.", src: "5. Mose 6,9", lv: 1 },
  { cat: "Alltag", q: "Ein Gebetbuch auf den Boden legen", a: "nein", e: "Heilige Bücher behandelt man mit Respekt – fällt eines herunter, heben viele es auf und küssen es.", lv: 3 },
  { cat: "Alltag", q: "Einen Obstbaum fällen, nur weil er im Weg ist", a: "nein", e: "Fruchttragende Bäume grundlos zu zerstören ist verboten. Daraus leiten Rabbiner das allgemeine Verbot ab, Dinge zu verschwenden („Bal Taschchit“).", src: "5. Mose 20,19", lv: 3 },
  { cat: "Alltag", q: "Genießbares Essen in den Müll werfen", a: "nein", e: "Verschwendung fällt unter „Bal Taschchit“.", src: "5. Mose 20,19", lv: 2 },
  { cat: "Alltag", q: "Im Laden mit einer manipulierten Waage wiegen", a: "nein", e: "Falsche Maße und Gewichte verbietet die Tora ausdrücklich.", src: "5. Mose 25,13–16", lv: 1 },
  { cat: "Alltag", q: "Einen Weihnachtsbaum aufstellen", a: "nein", e: "Der Weihnachtsbaum gehört zu einem christlichen Fest – für religiöse Juden kommt das nicht in Frage.", lv: 2 },
  { cat: "Alltag", q: "Den eigenen Geburtstag feiern", a: "ja", e: "Dafür gibt es kein Verbot. Viele nehmen den Tag zum Anlass, besonders viel zu spenden oder Gutes zu tun.", lv: 2 },
  { cat: "Alltag", q: "In der Trauerwoche (Schiwa) Musik hören", a: "nein", e: "In den sieben Trauertagen nach einer Beerdigung verzichtet man auf Musik, Feiern und Arbeit.", src: "Schulchan Aruch, Jore De’a 380", lv: 3 },
  { cat: "Alltag", q: "Milchgeschirr im Fleisch-Spülbecken spülen", a: "nein", e: "In koscheren Küchen gibt es getrenntes Geschirr für Milch und Fleisch – oft sogar zwei Spülbecken.", src: "Schulchan Aruch, Jore De’a 95", lv: 3 },
  { cat: "Alltag", q: "Eine Mikrowelle für Fleisch und Milch benutzen", a: "kommt", e: "Mit abgedecktem Essen und Regeln zum „Kaschern“ halten manche Rabbiner das für möglich, viele Familien haben aber lieber zwei Geräte.", lv: 3 },
  { cat: "Alltag", q: "Schwarzen Filterkaffee in einem normalen Café trinken", a: "kommt", e: "Kaffee selbst ist koscher. Fragen gibt es beim Geschirr und den Maschinen – viele Rabbiner erlauben einfachen schwarzen Kaffee.", lv: 3 },
  { cat: "Alltag", q: "Um Geld Karten spielen", a: "kommt", e: "Glücksspiel ist nicht ausdrücklich verboten, aber verpönt: Wer nur vom Spielen lebt, darf nach dem Talmud nicht als Zeuge auftreten.", src: "Talmud, Sanhedrin 24b", lv: 3 },

  // ---- 2026-11-13 ----
  { cat: "Alltag", q: "In der Klassenarbeit abschreiben", a: "nein", e: "Andere zu täuschen („Genevat Da’at“, wörtlich: Diebstahl des Wissens) ist verboten – laut Talmud gegenüber jedem Menschen. Wer abschreibt, täuscht den Lehrer über sein Können.", src: "Talmud, Chullin 94a", lv: 1, d: "2026-11-13" },
  { cat: "Alltag", q: "Jemanden im Klassenchat öffentlich bloßstellen", a: "nein", e: "Der Talmud vergleicht es mit Blutvergießen, einen Menschen öffentlich zu beschämen: Erst wird das Gesicht rot, dann weicht das Blut daraus.", src: "Talmud, Bava Metzia 58b", lv: 1, d: "2026-11-13" },
  { cat: "Alltag", q: "Einem Mitschüler das Ladekabel nicht leihen, weil er dir seins auch nicht geliehen hat", a: "nein", e: "Genau so erklärt der Talmud das Verbot der Rache: „Du hast mir nicht geliehen, also leihe ich dir auch nicht.“ Die Tora sagt: Räche dich nicht und trage nichts nach.", src: "3. Mose 19,18; Talmud, Joma 23a", lv: 1, d: "2026-11-13" },
  { cat: "Essen", q: "Fisch und Fleisch zusammen essen", a: "nein", e: "Fisch ist parve, wird aber nicht zusammen mit Fleisch gegessen – der Talmud nennt dafür eine Gesundheitsgefahr. Zwischen den Gängen spült man den Mund aus oder isst etwas Neutrales.", src: "Schulchan Aruch, Jore De’a 116,2", lv: 2, d: "2026-11-13" },
  { cat: "Essen", q: "Wachteln essen", a: "ja", e: "Wachteln gelten als koschere Vögel – die Tora erzählt, dass die Israeliten in der Wüste Wachteln aßen. Wie jedes Geflügel müssen sie geschächtet werden.", src: "2. Mose 16,13", lv: 3, d: "2026-11-13" },
  { cat: "Essen", q: "Äpfel von einem Baum, der erst zwei Jahre alt ist", a: "nein", e: "Früchte aus den ersten drei Jahren eines Baumes heißen „Orla“ und werden nicht gegessen. Nach der Tradition gilt das auch außerhalb Israels.", src: "3. Mose 19,23", lv: 3, d: "2026-11-13" },
  { cat: "Alltag", q: "Dem Babysitter den Lohn erst nächste Woche zahlen", a: "nein", e: "Die Tora sagt: Der Lohn eines Arbeiters soll nicht über Nacht bei dir bleiben. Wer für dich gearbeitet hat und sein Geld haben will, bekommt es rechtzeitig.", src: "3. Mose 19,13", lv: 2, d: "2026-11-13" },
  { cat: "Alltag", q: "Einen Apfel ohne Segensspruch essen", a: "nein", e: "Vor dem Essen sagt man eine Bracha. Der Talmud sagt: Wer etwas von dieser Welt genießt, ohne zu segnen, ist, als hätte er sich an Heiligem vergriffen.", src: "Talmud, Berachot 35a", lv: 2, d: "2026-11-13" },
  { cat: "Schabbat", q: "Am Schabbat Fingernägel schneiden", a: "nein", e: "Nägel oder Haare zu schneiden gilt am Schabbat als „Scheren“, eine der verbotenen Arbeiten. Deshalb schneidet man sie am Freitag.", src: "Schulchan Aruch, Orach Chajim 340,1", lv: 3, d: "2026-11-13" },
  { cat: "Feiertage", q: "An Rosch Haschana den Schofar hören", a: "ja", e: "Das Widderhorn zu hören ist das zentrale Gebot von Rosch Haschana – die Tora nennt den Tag „Jom Terua“, Tag des Blasens. Fällt das Fest auf einen Schabbat, wird allerdings nicht geblasen.", src: "4. Mose 29,1", lv: 1, d: "2026-11-14" },
  { cat: "Alltag", q: "Die eigenen Eltern beim Vornamen ansprechen", a: "nein", e: "Zum Gebot, Vater und Mutter zu ehren, gehört, sie nicht einfach beim Vornamen zu rufen. Man sagt „Papa“, „Mama“ oder eine andere respektvolle Anrede.", src: "Schulchan Aruch, Jore De’a 240,2", lv: 2, d: "2026-11-14" },
  { cat: "Alltag", q: "Ein Geheimnis weitererzählen, das dir ein Freund anvertraut hat", a: "nein", e: "Der Talmud lehrt: Was dir jemand erzählt, darfst du nicht weitersagen, bis er es dir ausdrücklich erlaubt. Das gilt erst recht für Geheimnisse.", src: "Talmud, Joma 4b", lv: 1, d: "2026-11-14" },
  { cat: "Alltag", q: "Einen Mitschüler mit einem gemeinen Spitznamen rufen", a: "nein", e: "Der Talmud zählt es zu den schweren Vergehen, jemandem einen kränkenden Beinamen zu geben – selbst wenn sich alle schon daran gewöhnt haben.", src: "Talmud, Bava Metzia 58b", lv: 1, d: "2026-11-14" },
  { cat: "Essen", q: "Rinderleber essen, die nur gesalzen und dann gekocht wurde", a: "nein", e: "Leber enthält so viel Blut, dass Einsalzen nicht reicht. Sie muss über offenem Feuer gegrillt werden, damit das Blut herausläuft – erst dann darf sie gekocht werden.", src: "Schulchan Aruch, Jore De’a 73,1", lv: 3, d: "2026-11-14" },
  { cat: "Essen", q: "Fleisch von einem Rind essen, das von selbst gestorben ist", a: "nein", e: "Die Tora verbietet, ein Tier zu essen, das von selbst verendet ist (Nevela) – auch wenn es eine koschere Tierart ist. Erlaubt ist nur Fleisch von korrekt geschächteten Tieren.", src: "5. Mose 14,21", lv: 2, d: "2026-11-14" },
  { cat: "Essen", q: "Brot essen, ohne sich vorher rituell die Hände zu waschen", a: "nein", e: "Vor dem Essen von Brot gießt man Wasser über die Hände (Netilat Jadajim) und sagt einen Segensspruch. Bei Obst oder Joghurt ist das nicht nötig.", src: "Schulchan Aruch, Orach Chajim 158,1", lv: 3, d: "2026-11-14" },
  { cat: "Alltag", q: "Selbst essen, bevor man dem hungrigen Haustier sein Futter gibt", a: "nein", e: "Der Talmud leitet aus der Tora ab: Erst bekommt das Tier sein Futter, dann isst man selbst. Wer ein Tier hält, ist für es verantwortlich.", src: "Talmud, Berachot 40a", lv: 3, d: "2026-11-14" },
  { cat: "Alltag", q: "Für einen alten Menschen aufstehen, wenn er hereinkommt", a: "ja", e: "Die Tora sagt: Vor grauem Haar sollst du aufstehen und das Alter ehren. Aufstehen, Platz anbieten oder die Tür aufhalten sind gelebter Respekt.", src: "3. Mose 19,32", lv: 1, d: "2026-11-14" },
  { cat: "Schabbat", q: "Am Schabbat Hausaufgaben schreiben", a: "nein", e: "Schreiben gehört zu den 39 Arbeiten, die am Schabbat verboten sind – schon zwei Buchstaben zählen. Lesen und Lernen sind dagegen erlaubt.", src: "Mischna, Schabbat 7,2", lv: 2, d: "2026-11-14" },
  { cat: "Feiertage", q: "Den Chanukka-Leuchter ins Fenster stellen", a: "ja", e: "Die Lichter sollen das Wunder öffentlich bekannt machen. Der Talmud empfiehlt deshalb, sie an die Haustür oder ins Fenster zur Straße zu stellen.", src: "Talmud, Schabbat 21b", lv: 2, d: "2026-11-15" },
  { cat: "Alltag", q: "Einen Freund heimlich hassen, statt mit ihm über den Streit zu reden", a: "nein", e: "Die Tora sagt: Du sollst deinen Bruder nicht in deinem Herzen hassen – weise ihn lieber zurecht. Wer sich gekränkt fühlt, soll es offen und freundlich ansprechen, statt Groll zu sammeln.", src: "3. Mose 19,17", lv: 1, d: "2026-11-15" },
  { cat: "Alltag", q: "Ein gefundenes Handy behalten, obwohl man weiß, wem es gehört", a: "nein", e: "Die Tora verpflichtet, verlorene Sachen dem Besitzer zurückzubringen, und sagt: Du darfst dich nicht abwenden. Wer weiß, wem etwas gehört, muss es zurückgeben.", src: "5. Mose 22,1–3", lv: 1, d: "2026-11-15" },
  { cat: "Alltag", q: "Einem Mitschüler absichtlich einen schlechten Rat geben, damit er scheitert", a: "nein", e: "Die Tora verbietet, einem Blinden ein Hindernis in den Weg zu legen. Raschi erklärt, dass damit auch gemeint ist, jemandem einen Rat zu geben, der ihm schadet.", src: "3. Mose 19,14", lv: 1, d: "2026-11-15" },
  { cat: "Essen", q: "Das Talgfett (Chelev) vom Rind essen", a: "nein", e: "Die Tora verbietet bestimmte Fettteile von Rind, Schaf und Ziege. Der Metzger entfernt sie beim koscheren Zubereiten – normales Muskelfett darf man dagegen essen.", src: "3. Mose 7,23", lv: 3, d: "2026-11-15" },
  { cat: "Essen", q: "Fleisch von einem Rind essen, das ein Wolf gerissen hat", a: "nein", e: "Die Tora sagt: Fleisch, das auf dem Feld zerrissen wurde, sollt ihr nicht essen. Ein Tier mit solchen tödlichen Verletzungen gilt als Trefa – auch wenn es eine koschere Tierart ist.", src: "2. Mose 22,30", lv: 2, d: "2026-11-15" },
  { cat: "Essen", q: "Brot essen, in dessen Teig Milch eingebacken wurde", a: "kommt", e: "Normales Brot soll nicht mit Milch gebacken werden, damit man es nicht aus Versehen zum Fleisch isst. Erlaubt ist es, wenn das Brot eine besondere Form hat oder nur eine kleine Menge gebacken wird.", src: "Schulchan Aruch, Jore De’a 97,1", lv: 3, d: "2026-11-15" },
  { cat: "Alltag", q: "Junge Vögel aus dem Nest nehmen, während die Mutter darauf sitzt", a: "nein", e: "Die Tora sagt: Wenn du ein Vogelnest findest, nimm nicht die Mutter mit den Jungen – lass die Mutter zuerst fortfliegen. Das Gebot lehrt Rücksicht auf Tiere.", src: "5. Mose 22,6–7", lv: 3, d: "2026-11-15" },
  { cat: "Alltag", q: "Ein Haus mit begehbarem Flachdach ohne Geländer bauen", a: "nein", e: "Die Tora verlangt ein Geländer am Dach, damit niemand herunterfällt. Daraus lernt man: Man muss Gefahren im eigenen Haus beseitigen.", src: "5. Mose 22,8", lv: 3, d: "2026-11-15" },
  { cat: "Feiertage", q: "Vor Jom Kippur einen Freund um Verzeihung bitten, den man gekränkt hat", a: "ja", e: "Die Mischna lehrt: Jom Kippur sühnt Sünden zwischen Mensch und Gott – Unrecht gegenüber anderen Menschen aber erst, wenn man sich mit ihnen versöhnt hat. Deshalb bittet man vorher um Verzeihung.", src: "Mischna, Joma 8,9", lv: 2, d: "2026-11-15" },
  { cat: "Schabbat", q: "Am Freitagabend den Kiddusch über einen Becher Wein sprechen", a: "ja", e: "Das Gebot, den Schabbat zu heiligen, erfüllt man laut Talmud mit einem Segensspruch über Wein zu Beginn des Schabbats. Statt Wein kann man auch Traubensaft nehmen.", src: "Talmud, Pesachim 106a", lv: 1, d: "2026-11-15" },
  { cat: "Essen", q: "Ein Hühnerei zum Frühstück essen", a: "ja", e: "Die Mischna lehrt: Was von einem koscheren Tier stammt, ist koscher. Weil das Huhn ein koscherer Vogel ist, sind auch seine Eier koscher – und sie gelten weder als Fleisch noch als Milch.", src: "Mischna, Bechorot 1,2", lv: 1, d: "2026-11-16" },
  { cat: "Essen", q: "Gemüse essen, das in einem Topf gekocht wurde, in dem vorher Schweinefleisch gekocht wurde", a: "nein", e: "Töpfe nehmen den Geschmack der Speisen auf, die darin gekocht werden. Ein nicht koscherer Topf muss deshalb erst gekaschert werden – das leitet man aus der Tora ab, wo Metallgefäße durch Feuer oder Wasser gereinigt werden mussten.", src: "4. Mose 31,23", lv: 3, d: "2026-11-16" },
  { cat: "Essen", q: "Ein Stück Fleisch essen, das von einem noch lebenden Tier abgeschnitten wurde", a: "nein", e: "Die Tora verbietet, „das Leben mit dem Fleisch“ zu essen. Daraus lernt man das Verbot, ein Glied von einem lebenden Tier zu essen – selbst wenn das Tier an sich koscher ist.", src: "5. Mose 12,23", lv: 3, d: "2026-11-16" },
  { cat: "Alltag", q: "Den Eltern im Haushalt helfen, wenn sie darum bitten", a: "ja", e: "„Ehre deinen Vater und deine Mutter“ ist eines der Zehn Gebote. Zum Ehren der Eltern gehört auch, ihnen zu helfen und sie zu unterstützen.", src: "2. Mose 20,12", lv: 1, d: "2026-11-16" },
  { cat: "Alltag", q: "Einem Armen, der um Hilfe bittet, gar nichts geben", a: "nein", e: "Die Tora sagt: Verhärte dein Herz nicht und verschließe deine Hand nicht vor deinem armen Bruder. Wer helfen kann, soll Bedürftigen etwas geben – und sei es nur wenig.", src: "5. Mose 15,7", lv: 2, d: "2026-11-16" },
  { cat: "Alltag", q: "Beim Online-Verkauf verschweigen, dass die Spielkonsole einen Defekt hat", a: "nein", e: "Die Tora verbietet, einander beim Kaufen und Verkaufen zu übervorteilen. Wer einen bekannten Mangel verschweigt, betrügt den Käufer.", src: "3. Mose 25,14", lv: 2, d: "2026-11-16" },
  { cat: "Alltag", q: "Einen kranken Mitschüler besuchen", a: "ja", e: "Kranke zu besuchen (Bikkur Cholim) ist ein wichtiges Gebot. Der Talmud sagt, wer einen Kranken besucht, nimmt ihm einen Teil seines Leidens ab.", src: "Talmud, Nedarim 39b", lv: 1, d: "2026-11-16" },
  { cat: "Alltag", q: "Einem Mitschüler zum Spaß etwas aus dem Rucksack nehmen und es später zurückgeben", a: "nein", e: "Auch Stehlen „nur aus Spaß“ oder mit der Absicht, es zurückzugeben, ist verboten. So soll man sich gar nicht erst an das Wegnehmen fremder Sachen gewöhnen.", src: "Schulchan Aruch, Choschen Mischpat 348,1", lv: 3, d: "2026-11-16" },
  { cat: "Schabbat", q: "Am Schabbat die Mahlzeit mit zwei ganzen Broten (Challot) beginnen", a: "ja", e: "Der Talmud lehrt, dass man am Schabbat den Segen über zwei ganze Brote spricht. Das erinnert an das Manna in der Wüste, von dem es vor dem Schabbat eine doppelte Portion gab.", src: "Talmud, Schabbat 117b", lv: 2, d: "2026-11-16" },
  { cat: "Feiertage", q: "An Rosch Haschana einen Apfel in Honig tunken und essen", a: "ja", e: "Viele Gemeinden essen an Rosch Haschana einen süßen Apfel mit Honig – als Zeichen für ein gutes, süßes neues Jahr. Es ist ein verbreiteter Brauch, kein Gebot aus der Tora.", src: "Rema zu Orach Chajim 583,1", lv: 2, d: "2026-11-16" },
  { cat: "Alltag", q: "Einem Freund versprechen, ihm beim Lernen zu helfen, und es dann ohne Grund nicht tun", a: "nein", e: "Der Talmud leitet aus der Tora ab: Dein Ja soll ein ehrliches Ja sein und dein Nein ein ehrliches Nein. Man soll nichts zusagen, was man nicht ernst meint.", src: "Talmud, Bava Metzia 49a", lv: 2, d: "2026-11-18" },
  { cat: "Körper", q: "Für ein cooles Video auf einen fahrenden Zug klettern", a: "nein", e: "Das eigene Leben zu schützen ist in der Halacha eine Pflicht. Der Talmud sagt sogar: Gefahr wiegt schwerer als ein Verbot – gefährliche Mutproben sind deshalb nicht erlaubt.", src: "Talmud, Chullin 10a", lv: 1, d: "2026-11-18" },
  { cat: "Alltag", q: "Einem Mitschüler, der sich gebessert hat, ständig seine alten Fehler vorhalten", a: "nein", e: "Die Mischna zählt das zu den verletzenden Worten (Ona'at Dewarim): Wer bereut und sich geändert hat, dem soll man nicht sagen „Denk daran, was du früher getan hast“.", src: "Talmud, Bava Metzia 58b", lv: 3, d: "2026-11-18" },
  { cat: "Essen", q: "Forelle essen", a: "ja", e: "Die Forelle hat Flossen und Schuppen – beides verlangt die Tora bei Fischen. Deshalb ist sie koscher.", src: "3. Mose 11,9", lv: 1, d: "2026-11-18" },
  { cat: "Essen", q: "Blut aus dem eigenen Zahnfleisch herunterschlucken", a: "ja", e: "Tierblut ist verboten, und menschliches Blut, das sich abgetrennt hat (etwa auf einem Brot), haben die Rabbinen verboten. Blut, das im Mund aus dem Zahnfleisch kommt, darf man laut Talmud aber einfach herunterschlucken.", src: "Talmud, Ketubot 60a", lv: 3, d: "2026-11-18" },
  { cat: "Essen", q: "Einen großen Brotteig backen, ohne ein Stück Teig (Challa) abzutrennen", a: "nein", e: "Die Tora gebietet, vom Teig einen Teil abzugeben. Ab einer bestimmten Teigmenge trennt man deshalb vor dem Backen ein kleines Stück ab – erst dann darf das Brot gegessen werden.", src: "4. Mose 15,20", lv: 2, d: "2026-11-18" },
  { cat: "Alltag", q: "Ein paar verstreute Münzen auf dem Gehweg finden und behalten", a: "ja", e: "Die Mischna zählt verstreute Münzen zu den Funden, die man behalten darf: Sie haben kein Erkennungszeichen, und der Besitzer hat sie längst aufgegeben. Anders ist es, wenn man weiß, wem etwas gehört.", src: "Talmud, Bava Metzia 21a", lv: 2, d: "2026-11-18" },
  { cat: "Alltag", q: "Im Laden nach dem Preis fragen, obwohl man gar nicht vorhat, etwas zu kaufen", a: "nein", e: "Die Mischna verbietet, einen Verkäufer nach dem Preis zu fragen, wenn man nicht kaufen will. Man weckt falsche Hoffnungen – auch das zählt zu den verletzenden Worten.", src: "Talmud, Bava Metzia 58b", lv: 3, d: "2026-11-18" },
  { cat: "Schabbat", q: "Am Schabbat Wäsche in der Waschmaschine waschen", a: "nein", e: "Waschen und Reinigen von Stoff (Melaben) gehört zu den 39 Arbeiten, die am Schabbat verboten sind. Dazu kommt, dass man die Maschine einschalten müsste.", src: "Talmud, Schabbat 73a", lv: 1, d: "2026-11-18" },
  { cat: "Feiertage", q: "Am Sederabend vier Becher Wein trinken", a: "ja", e: "Die Mischna sagt: Am Sederabend soll jeder, auch der Ärmste, mindestens vier Becher Wein trinken – als Zeichen der Freiheit. Viele nehmen heute auch Traubensaft.", src: "Talmud, Pesachim 99b", lv: 2, d: "2026-11-18" },
  { cat: "Alltag", q: "Den geliehenen Controller eines Freundes aus Unachtsamkeit kaputt machen und nicht ersetzen", a: "nein", e: "Wer sich etwas leiht, haftet laut Tora dafür, wenn es bei ihm kaputtgeht oder verloren geht. Erst recht muss man ersetzen, was man durch eigene Unachtsamkeit beschädigt hat.", src: "2. Mose 22,13", lv: 2, d: "2026-11-19" },
  { cat: "Alltag", q: "Im Streit die Hand gegen einen Mitschüler erheben, um ihn zu schlagen", a: "nein", e: "Der Talmud sagt: Wer die Hand gegen einen anderen erhebt, wird schon „Frevler“ genannt – selbst wenn er gar nicht zuschlägt.", src: "Talmud, Sanhedrin 58b", lv: 1, d: "2026-11-19" },
  { cat: "Alltag", q: "Einem Gerücht über einen Mitschüler einfach glauben", a: "nein", e: "Verboten ist nicht nur, üble Nachrede (Laschon Hara) zu erzählen, sondern auch, sie bereitwillig zu glauben. Der Talmud tadelt den, der sie annimmt, genauso scharf wie den, der sie verbreitet.", src: "Talmud, Pesachim 118a", lv: 3, d: "2026-11-19" },
  { cat: "Essen", q: "Gans essen", a: "ja", e: "Bei Vögeln nennt die Tora nur die verbotenen Arten. Der Talmud sagt, dass man Vögel nach Überlieferung isst – und die Gans gilt seit jeher als koscherer Vogel, wenn sie richtig geschächtet wurde.", src: "Talmud, Chullin 63b", lv: 1, d: "2026-11-19" },
  { cat: "Essen", q: "Fisch essen, der nicht geschächtet wurde", a: "ja", e: "Fische brauchen keine Schächtung – das leitet der Talmud aus der Tora ab. Koscher ist ein Fisch, wenn er Flossen und Schuppen hat.", src: "Talmud, Chullin 27b", lv: 3, d: "2026-11-19" },
  { cat: "Essen", q: "Für den Hund Rindfleisch in Milch kochen", a: "nein", e: "Fleisch mit Milch ist nicht nur zum Essen verboten: Schon das Zusammenkochen ist verboten, und man darf auch keinen Nutzen davon haben – also es auch nicht dem Hund geben.", src: "Talmud, Chullin 115b", lv: 3, d: "2026-11-19" },
  { cat: "Alltag", q: "Sich auf den festen Stammplatz des Vaters setzen", a: "nein", e: "Zur Ehrfurcht vor den Eltern gehört laut Talmud, nicht auf dem festen Platz des Vaters zu stehen oder zu sitzen und ihm nicht zu widersprechen. Erlaubt der Vater es ausdrücklich, ist es in Ordnung.", src: "Talmud, Kidduschin 31b", lv: 3, d: "2026-11-19" },
  { cat: "Alltag", q: "Einem Tier helfen, das unter seiner schweren Last zusammengebrochen ist", a: "ja", e: "Die Tora gebietet ausdrücklich, einem Esel, der unter seiner Last liegt, wieder aufzuhelfen – sogar dem Esel von jemandem, mit dem man verfeindet ist.", src: "2. Mose 23,5", lv: 2, d: "2026-11-19" },
  { cat: "Schabbat", q: "Am Schabbat ein Lagerfeuer anzünden", a: "nein", e: "Die Tora sagt ausdrücklich: Ihr sollt am Schabbattag in all euren Wohnungen kein Feuer anzünden. Feuermachen gehört zu den verbotenen Arbeiten.", src: "2. Mose 35,3", lv: 1, d: "2026-11-19" },
  { cat: "Feiertage", q: "An Sukkot den Feststrauß (Lulav) in die Hand nehmen", a: "ja", e: "Die Tora gebietet, an Sukkot vier Pflanzenarten zu nehmen: Palmzweig, Etrog, Myrte und Bachweide. Man hält sie zusammen und spricht einen Segen darüber.", src: "3. Mose 23,40", lv: 2, d: "2026-11-19" },
  { cat: "Alltag", q: "Zwischen zwei zerstrittenen Freunden vermitteln, damit sie sich wieder vertragen", a: "ja", e: "Frieden zwischen Menschen zu stiften gehört laut Talmud zu den Taten, deren Lohn man schon in dieser Welt genießt. Streit schlichten ist also eine besonders gute Tat.", src: "Talmud, Schabbat 127a", lv: 1, d: "2026-11-20" },
  { cat: "Alltag", q: "Einem Freund Geld leihen, wenn er gerade knapp bei Kasse ist", a: "ja", e: "Die Tora spricht davon, Geld an Bedürftige zu leihen, und verbietet dabei, Zinsen zu nehmen. Jemandem in Not mit einem Darlehen zu helfen, gilt als Gebot.", src: "2. Mose 22,24", lv: 2, d: "2026-11-20" },
  { cat: "Alltag", q: "Einem Mitschüler ein gebrauchtes Handy für viel mehr als den üblichen Preis verkaufen, ohne dass er es merkt", a: "nein", e: "Die Tora verbietet, beim Kaufen und Verkaufen den anderen zu übervorteilen. Laut Talmud kann der Käufer den Kauf sogar rückgängig machen, wenn der Preis mehr als ein Sechstel über dem Marktwert liegt.", src: "3. Mose 25,14", lv: 3, d: "2026-11-20" },
  { cat: "Essen", q: "Sardinen essen", a: "ja", e: "Sardinen haben Flossen und Schuppen. Laut Tora darf man alle Wassertiere essen, die beides haben.", src: "3. Mose 11,9", lv: 1, d: "2026-11-20" },
  { cat: "Essen", q: "Den Ischiasnerv (Gid haNasche) vom Rind essen", a: "nein", e: "Weil Jakob beim Kampf mit dem Engel an der Hüfte verletzt wurde, essen die Kinder Israels den Hüftnerv nicht. Deshalb muss er bei koscherem Fleisch sorgfältig entfernt werden.", src: "1. Mose 32,33", lv: 3, d: "2026-11-20" },
  { cat: "Essen", q: "Rehfleisch essen, wenn das Reh vorher richtig geschächtet wurde", a: "ja", e: "Reh und Hirsch sind wiederkäuende Tiere mit gespaltenen Hufen und werden in der Tora ausdrücklich als erlaubt genannt. Sie müssen aber geschächtet werden – ein bei der Jagd geschossenes Tier ist nicht koscher.", src: "5. Mose 14,5", lv: 2, d: "2026-11-20" },
  { cat: "Alltag", q: "Den alt gewordenen Eltern Essen und Trinken bringen", a: "ja", e: "Der Talmud erklärt, was es heißt, die Eltern zu ehren: ihnen zu essen und zu trinken geben, sie anziehen und ihnen beim Hinein- und Hinausgehen helfen.", src: "Talmud, Kidduschin 31b", lv: 1, d: "2026-11-20" },
  { cat: "Alltag", q: "Einem Ochsen beim Dreschen das Maul zubinden, damit er nichts vom Getreide frisst", a: "nein", e: "Die Tora sagt ausdrücklich: Du sollst dem Ochsen beim Dreschen nicht das Maul verbinden. Ein arbeitendes Tier darf vom Futter fressen, mit dem es arbeitet.", src: "5. Mose 25,4", lv: 3, d: "2026-11-20" },
  { cat: "Schabbat", q: "Am Schabbat eine Kerze auspusten", a: "nein", e: "Ein Feuer zu löschen gehört zu den 39 verbotenen Arbeiten am Schabbat. Deshalb lässt man die Schabbatkerzen von selbst herunterbrennen.", src: "Talmud, Schabbat 73a", lv: 1, d: "2026-11-20" },
  { cat: "Feiertage", q: "An Schawuot Milchspeisen wie Käsekuchen essen", a: "ja", e: "Es ist ein weit verbreiteter Brauch, am ersten Tag von Schawuot Milchspeisen zu essen. Das wird im Schulchan Aruch in den Anmerkungen von Rabbi Mosche Isserles erwähnt.", src: "Schulchan Aruch, Orach Chajim 494,3", lv: 2, d: "2026-11-20" },
  { cat: "Alltag", q: "Mit einem Fake-Profil im Internet andere Leute täuschen", a: "nein", e: "Der Talmud verbietet, Menschen zu täuschen oder ihnen einen falschen Eindruck zu vermitteln („Genevat Da’at“) – egal ob Juden oder Nichtjuden. Wer sich online als jemand anderes ausgibt, um andere hinters Licht zu führen, fällt genau darunter.", src: "Talmud, Chullin 94a", lv: 2, d: "2026-11-21" },
  { cat: "Alltag", q: "Tatenlos zusehen, wie ein Mitschüler auf dem Schulhof verprügelt wird", a: "nein", e: "Die Tora sagt: Du sollst nicht untätig beim Blut deines Nächsten stehen. Der Talmud leitet daraus ab, dass man jemandem in Gefahr helfen muss – etwa indem man dazwischengeht, wenn es sicher ist, oder sofort Lehrer oder andere Hilfe holt.", src: "3. Mose 19,16; Talmud, Sanhedrin 73a", lv: 2, d: "2026-11-21" },
  { cat: "Alltag", q: "Von seinem Taschengeld ein Zehntel spenden", a: "ja", e: "Nach dem Schulchan Aruch ist ein Zehntel des Einkommens für Zedaka (Wohltätigkeit) das übliche Maß, ein Fünftel das beste. Viele geben deshalb auch vom Taschengeld oder vom Ferienjob ein Zehntel („Ma’asser“) ab.", src: "Schulchan Aruch, Jore De’a 249,1", lv: 3, d: "2026-11-21" },
  { cat: "Essen", q: "Lammkoteletts vom koscheren Metzger essen", a: "ja", e: "Schafe sind Wiederkäuer mit gespaltenen Hufen und werden in der Tora ausdrücklich unter den erlaubten Tieren genannt. Beim koscheren Metzger ist das Fleisch richtig geschächtet und vorbereitet.", src: "5. Mose 14,4", lv: 1, d: "2026-11-21" },
  { cat: "Essen", q: "Kuhmilch aus dem Supermarkt trinken, bei deren Melken kein Jude dabei war", a: "kommt", e: "Der Schulchan Aruch verbietet Milch, die ein Nichtjude ohne jüdische Aufsicht gemolken hat – aus Sorge, dass Milch von unkoscheren Tieren beigemischt wurde. Viele Rabbiner, etwa Rabbi Mosche Feinstein, erlauben normale Milch, wenn staatliche Kontrollen das ausschließen; andere trinken nur „Chalav Jisrael“.", src: "Schulchan Aruch, Jore De’a 115,1", lv: 3, d: "2026-11-21" },
  { cat: "Essen", q: "Lachskaviar (Ketakaviar) essen", a: "ja", e: "Die Mischna lehrt: Was von einem koscheren Tier stammt, ist koscher. Der Lachs ist ein koscherer Fisch, deshalb sind auch seine Eier erlaubt – anders als Kaviar vom Stör. Man achtet aber auf ein Koscher-Siegel, damit nichts Unkoscheres beigemischt ist.", src: "Mischna, Bechorot 1,2", lv: 2, d: "2026-11-21" },
  { cat: "Alltag", q: "Nach einer Mahlzeit mit Brot das Tischgebet sprechen", a: "ja", e: "Die Tora sagt: Wenn du gegessen hast und satt bist, sollst du den Ewigen, deinen Gott, preisen. Daraus kommt das Tischgebet „Birkat haMason“ nach einer Mahlzeit mit Brot.", src: "5. Mose 8,10", lv: 1, d: "2026-11-21" },
  { cat: "Alltag", q: "Einen Gast beim Abschied noch ein Stück vor die Tür begleiten", a: "ja", e: "Der Talmud lobt es sehr, Gäste beim Gehen ein Stück zu begleiten („Levaja“), und sieht darin einen wichtigen Teil der Gastfreundschaft. Schon ein paar Schritte vor die Tür zeigen dem Gast Respekt.", src: "Talmud, Sota 46b", lv: 3, d: "2026-11-21" },
  { cat: "Feiertage", q: "Am Sederabend den Kindern vom Auszug aus Ägypten erzählen", a: "ja", e: "Die Tora gebietet: Du sollst deinem Sohn an jenem Tag erzählen, was der Ewige für dich getan hat, als du aus Ägypten zogst. Deshalb liest man am Sederabend die Haggada, und die Kinder stellen Fragen.", src: "2. Mose 13,8", lv: 1, d: "2026-11-21" },
  { cat: "Feiertage", q: "An Sukkot bei starkem Regen aus der Laubhütte ins Haus zum Essen gehen", a: "ja", e: "Die Mischna erlaubt, die Laubhütte zu verlassen, wenn es so stark regnet, dass das Essen verderben würde. Die Mizwa soll Freude machen – wer wegen des Regens leidet, ist davon befreit.", src: "Mischna, Sukka 2,9", lv: 3, d: "2026-11-21" },
  { cat: "Alltag", q: "Über einen gehörlosen Mitschüler schimpfen, weil er es ja nicht hören kann", a: "nein", e: "Die Tora verbietet ausdrücklich, einem Tauben zu fluchen – auch wenn er es nicht mitbekommt. Die Würde eines Menschen hängt nicht davon ab, ob er die Beleidigung hört.", src: "3. Mose 19,14", lv: 2, d: "2026-11-22" },
  { cat: "Alltag", q: "Einen neuen Mitschüler, der aus einem anderen Land kommt, ausgrenzen und schikanieren", a: "nein", e: "Die Tora gebietet: Einen Fremden sollst du nicht bedrängen, denn ihr wart selbst Fremde in Ägypten. Wer neu ist, soll freundlich aufgenommen werden.", src: "2. Mose 22,20", lv: 1, d: "2026-11-22" },
  { cat: "Alltag", q: "Für ein Referat einen fremden Text aus dem Internet kopieren und als eigenen ausgeben", a: "nein", e: "Der Talmud lobt, wer etwas im Namen dessen sagt, der es gesagt hat. Fremde Gedanken als eigene auszugeben täuscht andere (Genevat Da’at) und ist verboten.", src: "Talmud, Megilla 15a; Talmud, Chullin 94a", lv: 2, d: "2026-11-22" },
  { cat: "Essen", q: "Wildschwein essen", a: "nein", e: "Das Schwein hat zwar gespaltene Hufe, ist aber kein Wiederkäuer und deshalb nicht koscher. Das gilt genauso für das Wildschwein.", src: "3. Mose 11,7", lv: 1, d: "2026-11-22" },
  { cat: "Essen", q: "Pilze essen", a: "ja", e: "Pilze sind koscher, wenn sie frei von Insekten sind. Der Talmud legt fest, dass man über Pilze den allgemeinen Segensspruch „Schehakol“ sagt, weil sie ihre Nahrung nicht wie Pflanzen aus dem Boden ziehen.", src: "Talmud, Berachot 40b", lv: 2, d: "2026-11-22" },
  { cat: "Essen", q: "Am selben Tisch Fleisch essen, während dein Freund daneben Käse isst", a: "kommt", e: "Zwei Bekannte dürfen an einem Tisch nicht einfach Fleisch und Käse nebeneinander essen, weil sie sonst vom Essen des anderen nehmen könnten. Mit einem Erkennungszeichen, etwa einem eigenen Tischset oder einem Gegenstand dazwischen, ist es erlaubt.", src: "Schulchan Aruch, Jore De’a 88,2", lv: 3, d: "2026-11-22" },
  { cat: "Alltag", q: "Für ein neues, wertvolles Kleidungsstück den Segensspruch „Schehechejanu“ sagen", a: "ja", e: "Wer sich über neue, wertvolle Kleidung oder Geräte freut, dankt mit dem Segensspruch Schehechejanu. Je nach Brauch sagt man ihn beim Kauf oder beim ersten Anziehen.", src: "Schulchan Aruch, Orach Chajim 223,3", lv: 3, d: "2026-11-22" },
  { cat: "Alltag", q: "Einen Bekannten auf der Straße zuerst grüßen, statt zu warten, bis er grüßt", a: "ja", e: "Der Talmud erzählt von Rabban Jochanan ben Sakkai, dass ihn nie jemand zuerst gegrüßt hat – nicht einmal ein Fremder auf dem Markt. Zuerst zu grüßen gilt als gute Eigenschaft.", src: "Talmud, Berachot 17a", lv: 2, d: "2026-11-22" },
  { cat: "Schabbat", q: "Am Schabbat einen abgerissenen Knopf wieder annähen", a: "nein", e: "Nähen gehört zu den 39 Hauptarbeiten, die am Schabbat verboten sind. Schon zwei Stiche zählen als Nähen.", src: "Mischna, Schabbat 7,2", lv: 2, d: "2026-11-22" },
  { cat: "Feiertage", q: "An Purim Freunden ein Päckchen mit Essen schicken (Mischloach Manot)", a: "ja", e: "An Purim schickt man mindestens einem Freund zwei verschiedene essfertige Speisen. Das stärkt die Freundschaft und gehört zu den Geboten des Tages.", src: "Schulchan Aruch, Orach Chajim 695,4", lv: 2, d: "2026-11-22" },
  { cat: "Alltag", q: "Im Supermarkt einen Schokoriegel einstecken, ohne ihn zu bezahlen", a: "nein", e: "Die Tora sagt klar: Ihr sollt nicht stehlen. Das gilt auch für kleine, billige Dinge und auch dann, wenn es niemand merkt.", src: "3. Mose 19,11", lv: 1, d: "2026-11-23" },
  { cat: "Alltag", q: "Sich vor Freunden über die eigenen Eltern lustig machen", a: "nein", e: "Die Tora sagt: Verflucht ist, wer Vater oder Mutter verachtet. Die Eltern zu ehren heißt auch, nicht hinter ihrem Rücken abfällig über sie zu reden.", src: "5. Mose 27,16", lv: 2, d: "2026-11-23" },
  { cat: "Alltag", q: "Geld, das man sich von einem Freund geliehen hat, einfach nicht zurückzahlen, obwohl man es könnte", a: "nein", e: "Der Talmud sagt: Einen Gläubiger zu bezahlen ist ein Gebot (Mizwa). Wer Schulden hat und zahlen kann, muss sie auch zurückzahlen.", src: "Talmud, Ketubot 86a", lv: 1, d: "2026-11-23" },
  { cat: "Essen", q: "Ein Rindersteak aus dem normalen Supermarkt essen", a: "nein", e: "Auch das Fleisch eines koscheren Tieres ist nur erlaubt, wenn es nach jüdischem Ritus geschächtet und danach richtig vorbereitet wurde. Normales Supermarktfleisch erfüllt das nicht.", src: "5. Mose 12,21", lv: 1, d: "2026-11-23" },
  { cat: "Essen", q: "Fruchtgummis mit Gelatine aus koscherem Fisch essen", a: "ja", e: "Fische mit Flossen und Schuppen sind koscher, und Fisch muss nicht geschächtet werden. Gelatine aus ihrer Haut ist deshalb erlaubt, wenn sie unter Aufsicht hergestellt wurde.", src: "3. Mose 11,9", lv: 2, d: "2026-11-23" },
  { cat: "Essen", q: "Eine vegane Wurst essen, die wie Schinken schmeckt", a: "ja", e: "Der Talmud sagt: Für alles, was die Tora verboten hat, hat sie etwas Ähnliches erlaubt. Entscheidend ist, woraus ein Lebensmittel besteht, nicht wonach es schmeckt – die Wurst braucht aber trotzdem ein Koscher-Siegel.", src: "Talmud, Chullin 109b", lv: 3, d: "2026-11-23" },
  { cat: "Alltag", q: "Morgens nach dem Aufwachen rituell die Hände waschen", a: "ja", e: "Nach dem Aufstehen wäscht man die Hände mit einem Becher abwechselnd je dreimal und spricht einen Segensspruch. So beginnt man den Tag rein, bevor man betet.", src: "Schulchan Aruch, Orach Chajim 4,1", lv: 2, d: "2026-11-23" },
  { cat: "Alltag", q: "Als Mann an einem viereckigen Kleidungsstück Schaufäden (Zizit) tragen", a: "ja", e: "Die Tora gebietet, an die Ecken der Kleidung Schaufäden zu machen, damit man sich an die Gebote erinnert. Deshalb tragen viele jüdische Männer täglich ein kleines Gewand mit Zizit.", src: "4. Mose 15,38", lv: 1, d: "2026-11-23" },
  { cat: "Feiertage", q: "An Jom Kippur sich mit Bodylotion eincremen", a: "nein", e: "An Jom Kippur sind neben Essen und Trinken auch Waschen, Salben, Lederschuhe und eheliches Beisammensein verboten. Zum Salben zählt auch Eincremen mit Lotion.", src: "Mischna, Joma 8,1", lv: 2, d: "2026-11-23" },
  { cat: "Schabbat", q: "Als Mann am Schabbat Tefillin anlegen", a: "nein", e: "Tefillin sind ein Zeichen zwischen Gott und dem Volk Israel. Weil der Schabbat selbst schon ein solches Zeichen ist, legt man an Schabbat und Feiertagen keine Tefillin.", src: "Schulchan Aruch, Orach Chajim 31,1", lv: 3, d: "2026-11-23" },
  { cat: "Alltag", q: "Im Streit mit einem Freund leichtfertig „Ich schwöre bei Gott“ sagen", a: "nein", e: "Die Tora verbietet, den Namen Gottes leichtfertig oder grundlos auszusprechen. Wer im Streit einfach so bei Gott schwört, um recht zu bekommen, nimmt diesen Namen auf die leichte Schulter.", src: "2. Mose 20,7", lv: 2, d: "2026-11-24" },
  { cat: "Alltag", q: "Einem Mitschüler, der sich ehrlich entschuldigt, aus Trotz nicht verzeihen", a: "nein", e: "Die Mischna sagt: Wer um Verzeihung gebeten wird, soll nicht grausam sein und sie verweigern. Wer ehrlich bereut und sich entschuldigt, dem soll man vergeben.", src: "Mischna, Bava Kamma 8,7", lv: 2, d: "2026-11-24" },
  { cat: "Alltag", q: "Einen Freund nur zum Schein zu seiner Geburtstagsfeier einladen, obwohl man weiß, dass er nicht kommen kann", a: "nein", e: "Der Talmud verbietet, jemanden eindringlich einzuladen, wenn man weiß, dass er sowieso nicht kommt. Man will damit nur einen guten Eindruck machen – das ist Täuschung (Genevat Da’at).", src: "Talmud, Chullin 94a", lv: 3, d: "2026-11-24" },
  { cat: "Alltag", q: "Einen Mitschüler ohne jeden Beweis verdächtigen, dein Handy geklaut zu haben", a: "nein", e: "Der Talmud sagt: Wer ehrliche Menschen grundlos verdächtigt, wird dafür bestraft. Man soll andere nicht ohne Beweise beschuldigen, sondern ihnen zunächst Gutes zutrauen.", src: "Talmud, Schabbat 97a", lv: 3, d: "2026-11-24" },
  { cat: "Alltag", q: "Dem Vater vor anderen ins Wort fallen und ihm offen widersprechen", a: "nein", e: "Zur Ehrfurcht vor den Eltern gehört laut Talmud, ihnen nicht zu widersprechen und ihre Worte nicht zu „entscheiden“. Wenn der Vater sich irrt, darf man ihn respektvoll und behutsam darauf hinweisen.", src: "Talmud, Kidduschin 31b", lv: 3, d: "2026-11-24" },
  { cat: "Essen", q: "Hummer essen", a: "nein", e: "Die Tora erlaubt aus dem Wasser nur Tiere mit Flossen und Schuppen. Der Hummer hat beides nicht und ist deshalb nicht koscher.", src: "3. Mose 11,10", lv: 1, d: "2026-11-24" },
  { cat: "Essen", q: "Kabeljau essen", a: "ja", e: "Der Kabeljau hat Flossen und Schuppen und ist deshalb ein koscherer Fisch. Wie jedes Lebensmittel braucht er aber, wenn er verarbeitet ist, eine verlässliche Aufsicht.", src: "5. Mose 14,9", lv: 2, d: "2026-11-24" },
  { cat: "Essen", q: "Gänseschmalz aufs Brot essen", a: "ja", e: "Das Verbot von Talgfett (Chelev) gilt laut Tora nur für Rind, Schaf und Ziege. Das Fett von koscherem Geflügel wie der Gans ist erlaubt, wenn das Tier geschächtet wurde.", src: "3. Mose 7,23", lv: 3, d: "2026-11-24" },
  { cat: "Schabbat", q: "Nach dem Ende des Schabbat die Hawdala über Wein, Gewürze und eine Kerze sprechen", a: "ja", e: "Mit der Hawdala verabschiedet man den Schabbat. Man spricht die Segenssprüche über einen Becher Wein, über duftende Gewürze und über das Licht einer Kerze.", src: "Schulchan Aruch, Orach Chajim 296,1", lv: 2, d: "2026-11-24" },
  { cat: "Feiertage", q: "An Pessach Brot und anderes Gesäuertes (Chametz) im Haus aufbewahren", a: "nein", e: "Die Tora sagt: Sieben Tage lang soll kein Sauerteig in euren Häusern gefunden werden. Deshalb räumt man vor Pessach alles Gesäuerte aus dem Haus oder verkauft es.", src: "2. Mose 12,19", lv: 1, d: "2026-11-24" },
  { cat: "Alltag", q: "Ein Computerspiel illegal aus dem Internet herunterladen", a: "nein", e: "Im Talmud gilt der Grundsatz „Dina de-malchuta dina“: Das Gesetz des Landes ist auch für Juden bindend. Wer ein Spiel illegal herunterlädt, verstößt gegen das Urheberrecht und nimmt sich etwas, ohne dafür zu bezahlen.", src: "Talmud, Bava Kamma 113a", lv: 2, d: "2026-11-25" },
  { cat: "Alltag", q: "Einen Freund so lange bedrängen, bis er dir sein neues Handy verkauft, obwohl er es eigentlich behalten will", a: "nein", e: "Das Gebot „Du sollst nicht begehren“ verbietet nach der Halacha, jemanden so lange unter Druck zu setzen, bis er dir etwas überlässt, das er gar nicht hergeben will – selbst wenn du den vollen Preis bezahlst.", src: "2. Mose 20,17", lv: 3, d: "2026-11-25" },
  { cat: "Alltag", q: "Einen Freund ständig an geliehenes Geld erinnern, obwohl du weißt, dass er gerade nicht zahlen kann", a: "nein", e: "Die Tora sagt über den, der Geld geliehen hat: Du sollst ihn nicht wie ein drängender Gläubiger behandeln. Der Talmud leitet daraus ab, dass man jemanden, der gerade nicht zahlen kann, nicht unter Druck setzen darf.", src: "2. Mose 22,24; Talmud, Bava Metzia 75b", lv: 3, d: "2026-11-25" },
  { cat: "Essen", q: "Granatäpfel essen", a: "ja", e: "Obst ist grundsätzlich koscher. Der Granatapfel gehört sogar zu den sieben Früchten, für die die Tora das Land Israel lobt.", src: "5. Mose 8,8", lv: 1, d: "2026-11-25" },
  { cat: "Essen", q: "Miesmuscheln essen", a: "nein", e: "Koscher sind nur Wassertiere, die Flossen und Schuppen haben. Muscheln haben beides nicht und sind deshalb verboten – genau wie Shrimps und Hummer.", src: "3. Mose 11,10", lv: 1, d: "2026-11-25" },
  { cat: "Essen", q: "Fleisch von einem Rind essen, bei dem nach dem Schächten ein Loch in der Lunge gefunden wurde", a: "nein", e: "Nach dem Schächten wird die Lunge genau untersucht. Hat sie ein Loch, gilt das Tier als „Trefa“ (tödlich verletzt) und ist nicht koscher – auch wenn das Schächten selbst korrekt war.", src: "Mischna, Chullin 3,1", lv: 3, d: "2026-11-25" },
  { cat: "Alltag", q: "Einen neuen Kochtopf aus Metall benutzen, ohne ihn vorher in einer Mikwe einzutauchen", a: "nein", e: "Neues Geschirr aus Metall, das man von einem Nichtjuden oder in einem normalen Geschäft kauft, wird vor dem ersten Gebrauch in eine Mikwe (rituelles Tauchbad) getaucht. Das nennt man Tevilat Kelim.", src: "Schulchan Aruch, Jore De’a 120,1", lv: 3, d: "2026-11-25" },
  { cat: "Alltag", q: "Bei einem Freund einfach ohne Anklopfen ins Zimmer platzen", a: "nein", e: "Rabbi Akiva gab seinem Sohn den Rat, nicht einmal das eigene Haus unangekündigt zu betreten – erst recht nicht das Haus eines anderen. Anklopfen gehört zum guten Benehmen (Derech Erez).", src: "Talmud, Pesachim 112a", lv: 2, d: "2026-11-25" },
  { cat: "Schabbat", q: "Am Schabbat die brennenden Schabbatkerzen auf dem Tisch beiseiteschieben", a: "nein", e: "Brennende Kerzen sind am Schabbat „Muktze“ und dürfen nicht bewegt werden – unter anderem, weil die Flamme dabei ausgehen oder stärker brennen könnte. Deshalb stellt man sie schon vor Schabbat an ihren festen Platz.", src: "Schulchan Aruch, Orach Chajim 279,1", lv: 3, d: "2026-11-25" },
  { cat: "Schabbat", q: "Am Schabbat drei Mahlzeiten essen", a: "ja", e: "Es ist ein Gebot, am Schabbat drei Mahlzeiten zu essen: am Freitagabend, am Samstagmittag und eine dritte am Nachmittag (Seuda Schlischit).", src: "Schulchan Aruch, Orach Chajim 291,1", lv: 2, d: "2026-11-25" },
];
